async function signup(e){e.preventDefault();const m=document.querySelector("#smsg");m.textContent="Account wordt gemaakt…";const {data,error}=await supabase.auth.signUp({email:document.querySelector("#semail").value,password:document.querySelector("#spass").value,options:{data:{business_name:document.querySelector("#business").value},emailRedirectTo:location.origin}});if(error)m.textContent=error.message;else if(data.session)await dashboard();else m.textContent="Account gemaakt. Controleer uw e-mail om de registratie te bevestigen."}
async function dashboard(){const {data:{user}}=await supabase.auth.getUser();if(!user)return authView();const {data:mem,error:me}=await supabase.from("memberships").select("organization_id,role").eq("user_id",user.id).eq("active",true).single();if(me){app.innerHTML='<main class="shell"><div class="card">Account gevonden, maar organisatie kon niet worden geladen.</div></main>';return}const org=mem.organization_id;const view=new URLSearchParams(location.search).get("view")||"overview";const [p,l,co,t,h,leads,tasks,wf,wfissues,ap,pay,ints,appts,pays,audits]=await Promise.all([supabase.from("business_profiles").select("*").eq("organization_id",org).single(),supabase.from("leads").select("id",{count:"exact",head:true}).eq("organization_id",org),supabase.from("conversations").select("id",{count:"exact",head:true}).eq("organization_id",org),supabase.from("tasks").select("id",{count:"exact",head:true}).eq("organization_id",org).eq("status","open"),supabase.from("handoffs").select("id",{count:"exact",head:true}).eq("organization_id",org).eq("status","open"),supabase.from("leads").select("id,name,email,phone,status,source,score,summary,created_at").eq("organization_id",org).order("created_at",{ascending:false}).limit(50),supabase.from("tasks").select("id,title,status,priority,due_at").eq("organization_id",org).order("created_at",{ascending:false}).limit(12),supabase.from("workflow_actions").select("id",{count:"exact",head:true}).eq("organization_id",org).in("status",["pending","blocked","failed"]),supabase.from("workflow_actions").select("id,lead_id,action_type,channel,status,priority,attempts,max_attempts,provider,last_error,scheduled_at,created_at,updated_at").eq("organization_id",org).in("status",["blocked","failed"]).order("updated_at",{ascending:false}).limit(30),supabase.from("appointments").select("id",{count:"exact",head:true}).eq("organization_id",org).in("status",["requested","proposed","confirmed"]),supabase.from("customer_payments").select("id",{count:"exact",head:true}).eq("organization_id",org).neq("status","paid"),supabase.from("tenant_integrations").select("id,channel,provider,status,last_verified_at,last_error,config,capabilities").eq("organization_id",org).eq("is_default",true).order("channel"),supabase.from("appointments").select("id,lead_id,status,requested_text,start_at,end_at,timezone,provider,provider_booking_id,location,completed_at,created_at").eq("organization_id",org).order("created_at",{ascending:false}).limit(30),supabase.from("customer_payments").select("id,lead_id,appointment_id,status,amount_cents,currency,provider,provider_payment_id,payment_url,paid_at,created_at").eq("organization_id",org).order("created_at",{ascending:false}).limit(30),supabase.from("audit_events").select("id,actor_user_id,event_type,entity_type,entity_id,payload,created_at").eq("organization_id",org).order("created_at",{ascending:false}).limit(80)]);const integrations=ints.data||[];const workflowIssues=wfissues.data||[];const appointments=appts.data||[];const payments=pays.data||[];const auditEvents=audits.data||[];const leadById=id=>(leads.data||[]).find(x=>x.id===id);const byChannel=ch=>integrations.find(x=>x.channel===ch);const dtLocal=v=>{if(!v)return"";const d=new Date(v),z=new Date(d.getTime()-d.getTimezoneOffset()*60000);return z.toISOString().slice(0,16)};const money=(cents,currency="EUR")=>Number.isFinite(Number(cents))?new Intl.NumberFormat("nl-BE",{style:"currency",currency}).format(Number(cents)/100):"—";const profile=p.data||{}, nextAction=x=>x.status==="won"||x.status==="lost"?"Afgesloten":x.status==="handoff"?"Menselijke overname":(x.score||0)>=80?"Nu opvolgen":(x.score||0)>=60?"Vandaag opvolgen":"Verder kwalificeren", {data:orgrow}=await supabase.from("organizations").select("plan,trial_ends_at,subscription_status").eq("id",org).single();const configured=Boolean(profile.business_name&&profile.description&&arr(profile.services).length&&arr(profile.qualification_questions).length);const emailInt0=byChannel("email"),waInt0=byChannel("whatsapp"),emailReady=emailInt0?.status==="active",waReady=waInt0?.status==="active",calendarReady=byChannel("calendar")?.status==="active",paymentInt0=byChannel("payment"),paymentConnected=paymentInt0?.status==="active",paymentReady=Boolean(paymentConnected&&paymentInt0?.config?.stripe_mode==="live"),emailCaps=arr(emailInt0?.capabilities),waCaps=arr(waInt0?.capabilities),emailCan=t=>Boolean(emailReady&&emailCaps.includes(t)&&(t!=="review_request"||String(emailInt0?.config?.review_url||"").trim())),waCan=t=>{const x=waInt0?.config?.templates?.[t],vars=arr(x?.variables);return Boolean(waReady&&waCaps.includes(t)&&x?.name&&x?.language&&String(waInt0?.config?.phone_number_id||"").trim()&&/^v\d+\.\d+$/.test(String(waInt0?.config?.api_version||"").trim())&&(t!=="review_request"||String(waInt0?.config?.review_url||"").trim())&&(t!=="payment_link_send"||vars.includes("payment_url")))},actionReady=t=>emailCan(t)||waCan(t),ownerNotificationReady=Boolean(emailReady&&emailCaps.includes("notify_owner")),outboundReady=actionReady("lead_follow_up"),lifecycleReady=["lead_follow_up","appointment_confirmation","payment_link_send","review_request","retention_follow_up"].every(actionReady),profileReady=configured&&Boolean(profile.notification_email)&&Boolean(profile.automation_enabled)&&profile.widget_enabled!==false,coreReady=profileReady&&ownerNotificationReady&&outboundReady,fullReady=coreReady&&calendarReady&&paymentReady&&lifecycleReady;const readiness=[["Bedrijfsprofiel",profileReady,"Bedrijfsinfo, notificatieadres, widget en automatisering"],["Owner-notificatie",ownerNotificationReady,"Actieve e-mailroute voor gekwalificeerde leads en handoffs"],["Leadopvolging",outboundReady,"Uitvoerbaar e-mail- of WhatsApp-kanaal"],["Afspraakbevestiging",actionReady("appointment_confirmation"),"Minstens één kanaal kan afspraakupdates versturen"],["Betaallink bezorgen",actionReady("payment_link_send"),"Minstens één kanaal kan de unieke betaallink versturen"],["Reviewverzoek",actionReady("review_request"),"Reviewlink en uitvoerbaar kanaal aanwezig"],["Retentie",actionReady("retention_follow_up"),"Opvolgkanaal voor klanten met toestemming"],["Google Agenda",calendarReady,"Tenant-OAuth verbonden"],["Betaling",paymentReady,paymentConnected&&paymentInt0?.config?.stripe_mode==="test"?"Stripe is verbonden in testmodus":"Live Stripe Checkout + webhook actief"]];const readinessHtml=`<section class="card"><div class="sectionhead"><div><h2>Productiereadiness</h2><p class="muted">${fullReady?"Volledige end-to-end workflow actief.":coreReady?"Kernflow actief; agenda/betaling nog afwerken.":"Onboarding nog niet productieklaar."}</p></div><span class="badge">${fullReady?"READY":coreReady?"CORE READY":"SETUP"}</span></div><div class="grid">${readiness.map(x=>`<div class="step"><b>${x[1]?"✓":"○"} ${esc(x[0])}</b><span class="badge">${x[1]?"active":"needs_setup"}</span><p class="muted">${esc(x[2])}</p></div>`).join("")}</div>${!fullReady?'<a class="textlink" href="?view=integrations">Integraties afwerken →</a>':""}<div class="opbuttons"><button id="healthCheck" type="button" class="ghostbtn">Backendcontrole uitvoeren</button></div><div id="healthResult" class="result muted"></div></section>`;const trialActive=orgrow?.plan==="trial"&&new Date(orgrow.trial_ends_at).getTime()>Date.now();const trialEndLabel=orgrow?.trial_ends_at?new Date(orgrow.trial_ends_at).toLocaleDateString("nl-BE",{day:"2-digit",month:"2-digit",year:"numeric"}):"";const paidActive=["active","trialing"].includes(orgrow?.subscription_status||"");const rank={trial:99,starter:1,pro:2,business:3};const can=tier=>trialActive||(paidActive&&(rank[orgrow?.plan]||0)>=(rank[tier]||99));const lock=tier=>`<span class="badge">🔒 ${tier[0].toUpperCase()+tier.slice(1)}</span>`;const nav=x=>`<a class="navitem ${view===x?"active":""}" href="?view=${x}">${({overview:"Command Center",jarvis:"JARVIS",leads:"Leads",operations:"Operations",activity:"Activiteit",agents:"AI Agents",receptionist:"Receptionist",integrations:"Integraties",settings:"Instellingen",billing:"Facturatie"})[x]}</a>`;const shell=(body)=>`<main class="appShell"><aside class="sidebar"><div><div class="brand">Reception AI</div><div class="muted tenant">${esc(profile.business_name||user.email)}</div></div><nav>${["overview","jarvis","leads","operations","activity","agents","receptionist","integrations","settings","billing"].map(nav).join("")}</nav><div class="sidebottom"><span class="badge">${esc(orgrow?.plan||"trial")}</span><button class="small" id="logout">Uitloggen</button></div></aside><section class="workspace"><div class="mobilebar"><div class="brand">Reception AI</div><select id="mobileNav"><option value="overview" ${view==="overview"?"selected":""}>Command Center</option><option value="jarvis" ${view==="jarvis"?"selected":""}>JARVIS</option><option value="leads" ${view==="leads"?"selected":""}>Leads</option><option value="operations" ${view==="operations"?"selected":""}>Operations</option><option value="activity" ${view==="activity"?"selected":""}>Activiteit</option><option value="agents" ${view==="agents"?"selected":""}>AI Agents</option><option value="receptionist" ${view==="receptionist"?"selected":""}>Receptionist</option><option value="integrations" ${view==="integrations"?"selected":""}>Integraties</option><option value="settings" ${view==="settings"?"selected":""}>Instellingen</option><option value="billing" ${view==="billing"?"selected":""}>Facturatie</option></select></div>${body}${legalFooter()}</section></main>`;const metrics=`<section class="grid"><div class="card"><div class="muted">Leads</div><div class="metric">${l.count||0}</div></div><div class="card"><div class="muted">Gesprekken</div><div class="metric">${co.count||0}</div></div><div class="card"><div class="muted">Open follow-ups</div><div class="metric">${t.count||0}</div></div><div class="card"><div class="muted">Handoffs</div><div class="metric">${h.count||0}</div></div><div class="card"><div class="muted">Workflow wacht</div><div class="metric">${wf.count||0}</div></div><div class="card"><div class="muted">Afspraken actief</div><div class="metric">${ap.count||0}</div></div><div class="card"><div class="muted">Betalingen open</div><div class="metric">${pay.count||0}</div></div></section>`;let body="";
if(view==="overview")body=`<section class="pagehead"><span class="eyebrow">DASHBOARD</span><h1>Goed overzicht. Snelle opvolging.</h1><p class="muted">Bekijk wat uw AI-receptionist heeft opgevangen en wat menselijke aandacht nodig heeft.</p></section>${!configured?'<div class="notice"><b>Onboarding nog niet klaar.</b> Vul bedrijfsinformatie, diensten en kwalificatievragen in. <a href="?view=settings">Nu configureren →</a></div>':""}${readinessHtml}${metrics}<section class="card"><div class="sectionhead"><div><h2>Integraties</h2><p class="muted">Elke tenant gebruikt uitsluitend zijn eigen providerverbindingen. Niet-geconfigureerde kanalen blijven veilig geblokkeerd.</p></div></div><div class="grid">${["email","whatsapp","calendar","payment"].map(ch=>{const i=integrations.find(x=>x.channel===ch);const label={email:"E-mail",whatsapp:"WhatsApp",calendar:"Agenda",payment:"Betaling"}[ch];const state=i?.status||"needs_setup";return `<div class="step"><b>${esc(label)}</b><span class="badge">${esc(state)}</span><p class="muted">${esc(i?.provider||"Niet ingesteld")}</p>${i?.last_error?`<p class="error">${esc(i.last_error)}</p>`:""}</div>`}).join("")}</div></section><section class="twocol"><div class="card"><h2>Recente leads</h2><div class="flow">${(leads.data||[]).slice(0,6).map(x=>`<div class="step"><b>${esc(x.name||x.email||"Websitebezoeker")}</b><span class="score">score ${esc(x.score||0)}</span><p class="muted">${esc(x.summary||x.status)}</p></div>`).join("")||'<p class="muted">Nog geen leads.</p>'}</div><a class="textlink" href="?view=leads">Alle leads bekijken →</a></div><div class="card"><h2>Open opvolging</h2><div class="flow">${(tasks.data||[]).filter(x=>x.status==="open").map(x=>`<div class="step taskrow"><div><b>${esc(x.title)}</b><br><span class="muted">${esc(x.priority)}</span></div><button class="donebtn" data-id="${esc(x.id)}">Afhandelen</button></div>`).join("")||'<p class="muted">Alles bijgewerkt.</p>'}</div></div></section>`;
if(view==="operations")body=`<section class="pagehead"><span class="eyebrow">UITVOERING</span><h1>Operations</h1><p class="muted">Leg exacte afspraken vast, bevestig uitvoering en maak betaalverzoeken aan. Een verstreken afspraak wordt nooit vanzelf als uitgevoerd beschouwd.</p></section><section class="card"><h2>Afspraken</h2><div class="flow">${appointments.map(a=>{const lead=leadById(a.lead_id)||{};const payment=payments.find(p=>p.appointment_id===a.id&&p.status!=="paid")||payments.find(p=>p.appointment_id===a.id);return `<div class="step operationrow"><div><b>${esc(lead.name||lead.email||"Lead")}</b> <span class="badge">${esc(a.status)}</span><p class="muted">${esc(a.requested_text||"Geen aanvraagtekst")}</p>${a.provider_booking_id?`<p class="muted">Agenda: ${esc(a.provider||"provider")} · ${esc(a.provider_booking_id)}</p>`:""}<form class="apptform" data-id="${esc(a.id)}"><div class="chatmeta"><label>Start<input name="start" type="datetime-local" value="${esc(dtLocal(a.start_at))}"></label><label>Einde<input name="end" type="datetime-local" value="${esc(dtLocal(a.end_at))}"></label></div><label>Locatie<input name="location" value="${esc(a.location||"")}"></label><label>Status<select name="status"><option value="proposed" ${a.status==="proposed"?"selected":""}>Voorgesteld</option><option value="confirmed" ${a.status==="confirmed"?"selected":""}>Bevestigd</option></select></label><button>Planning opslaan</button></form><div class="opbuttons">${a.start_at&&a.end_at&&!["confirmed","completed","cancelled"].includes(a.status)?`<button class="confirmappt" data-id="${esc(a.id)}">Bevestig afspraak</button>`:""}${a.status==="confirmed"?(payment&&payment.status!=="paid"?`<button type="button" class="ghostbtn" disabled>Wacht op betaling</button>`:`<button class="completeappt" data-id="${esc(a.id)}">Markeer uitgevoerd</button>`):""}${a.status!=="completed"&&a.status!=="cancelled"?`<button class="cancelappt ghostbtn" data-id="${esc(a.id)}">Annuleer</button>`:""}</div>${["confirmed","completed"].includes(a.status)?`<form class="paymentform" data-appt="${esc(a.id)}" data-lead="${esc(a.lead_id)}"><label>Betaalbedrag (€)<input name="amount" type="number" min="0.01" step="0.01" value="${payment?.amount_cents?esc((payment.amount_cents/100).toFixed(2)):""}"></label><button>Betaalverzoek ${payment?"bijwerken":"aanmaken"}</button><span class="muted">${payment?`${esc(payment.status)} · ${esc(money(payment.amount_cents,payment.currency))}`:""}</span></form>`:a.status!=="cancelled"?'<p class="muted">Bevestig eerst de afspraak om een betaalverzoek aan te maken.</p>':""}</div><div class="opmsg muted" id="op-${esc(a.id)}"></div></div>`}).join("")||'<p class="muted">Nog geen afspraken.</p>'}</div></section><section class="card"><h2>Betalingen</h2><div class="flow">${payments.map(p=>{const lead=leadById(p.lead_id)||{};return `<div class="step"><b>${esc(lead.name||lead.email||"Lead")}</b> <span class="badge">${esc(p.status)}</span><p>${esc(money(p.amount_cents,p.currency))}</p><p class="muted">${esc(p.provider||"nog geen provider")}${p.provider_payment_id?" · "+esc(p.provider_payment_id):""}</p>${p.payment_url?`<a class="textlink" target="_blank" rel="noopener" href="${esc(p.payment_url)}">Open betaalpagina →</a>`:""}</div>`}).join("")||'<p class="muted">Nog geen betalingen.</p>'}</div></section><section class="card"><h2>Workflowproblemen</h2><p class="muted">Alleen geblokkeerde of definitief mislukte acties verschijnen hier. Provider- of OAuth-problemen hervatten meestal automatisch zodra de integratie hersteld is.</p><div class="flow">${workflowIssues.map(w=>{const lead=leadById(w.lead_id)||{};const unknown=String(w.last_error||"").toLowerCase().includes("delivery status is unknown");return `<div class="step"><div><b>${esc(w.action_type)}</b> <span class="badge">${esc(w.status)}</span><p class="muted">${esc(lead.name||lead.email||w.channel)} · ${esc(w.provider||w.channel)} · poging ${esc(w.attempts||0)}/${esc(w.max_attempts||5)}</p><p class="${unknown?"error":"muted"}">${esc(w.last_error||"Geen foutdetail")}</p></div><button class="retryworkflow" data-id="${esc(w.id)}" data-unknown="${unknown?"1":"0"}">Opnieuw proberen</button><div class="opmsg muted" id="wf-${esc(w.id)}"></div></div>`}).join("")||'<p class="muted">Geen geblokkeerde of mislukte workflowacties.</p>'}</div></section>`;
if(view==="activity")body=`<section class="pagehead"><span class="eyebrow">AUDITTRAIL</span><h1>Activiteit</h1><p class="muted">Recente gevoelige wijzigingen en workflowacties binnen deze organisatie. Credentials en tokens worden nooit in deze log opgeslagen.</p></section><section class="card"><div class="flow">${auditEvents.map(a=>{const when=new Date(a.created_at).toLocaleString("nl-BE",{dateStyle:"short",timeStyle:"short"});return `<div class="step"><div><b>${esc(a.event_type)}</b> <span class="badge">${esc(a.entity_type||"event")}</span><p class="muted">${esc(when)}${a.actor_user_id?" · gebruiker "+esc(String(a.actor_user_id).slice(0,8)):" · systeem"}</p><p class="muted">${esc(JSON.stringify(a.payload||{}))}</p></div></div>`}).join("")||'<p class="muted">Nog geen audit-events.</p>'}</div></section>`;
if(view==="jarvis")body=`<section class="pagehead"><span class="eyebrow">AI ORCHESTRATOR</span><h1>JARVIS</h1><p class="muted">Analyseert uw CRM, taken en handoffs en bepaalt welke agent nu de hoogste prioriteit heeft.</p>${can("business")?`<button id="jarvisRun" type="button">Analyseer mijn bedrijf</button>`:lock("business")}</section><section class="card"><div id="jarvisResult"><p class="muted">Nog geen analyse uitgevoerd.</p></div></section>`;
if(view==="leads")body=`<section class="pagehead"><span class="eyebrow">CRM</span><h1>Leads</h1><p class="muted">Kwalificeer en verplaats aanvragen door uw pipeline.</p></section><div class="card"><div class="flow leadlist">${(leads.data||[]).map(x=>`<div class="step leadrow"><div><b>${esc(x.name||x.email||"Websitebezoeker")}</b><div class="muted">${esc(x.email||x.phone||x.source)} · score ${esc(x.score||0)}</div><p>${esc(x.summary||"Geen samenvatting")}</p><div class="leadnext">AI-advies: <b>${esc(nextAction(x))}</b></div>${x.status==="won"?`${can("pro")?`<button class="reviewbtn" data-id="${esc(x.id)}">Review Agent</button>`:lock("pro")}<div class="reviewresult" id="review-${esc(x.id)}"></div>`:""}${!["won","lost"].includes(x.status)?`${can("pro")?`<button class="followbtn" data-id="${esc(x.id)}">Maak opvolging</button>`:lock("pro")}${can("business")?`<button class="salesbtn" data-id="${esc(x.id)}">Sales Agent</button>`:lock("business")}<div class="salesresult" id="sales-${esc(x.id)}"></div>`:""}</div><select class="leadstatus" data-id="${esc(x.id)}"><option value="new" ${x.status==="new"?"selected":""}>Nieuw</option><option value="qualifying" ${x.status==="qualifying"?"selected":""}>Kwalificeren</option><option value="qualified" ${x.status==="qualified"?"selected":""}>Gekwalificeerd</option><option value="follow_up" ${x.status==="follow_up"?"selected":""}>Opvolgen</option><option value="handoff" ${x.status==="handoff"?"selected":""}>Handoff</option><option value="won" ${x.status==="won"?"selected":""}>Gewonnen</option><option value="lost" ${x.status==="lost"?"selected":""}>Verloren</option></select></div>`).join("")||'<p class="muted">Nog geen leads.</p>'}</div></div>`;
if(view==="agents")body=`<section class="pagehead"><span class="eyebrow">AI WORKFORCE</span><h1>Uw AI-team</h1><p class="muted">Eén platform met gespecialiseerde agents. De Receptionist en Lead Agent gebruiken vandaag al uw live CRM-flow; de volgende agents worden stapsgewijs op dezelfde bedrijfscontext aangesloten.</p></section><section class="agentgrid"><article class="card agent live"><span class="agentstatus">ACTIEF</span><h2>🎧 Receptionist</h2><p class="muted">Beantwoordt websitevragen, herkent afspraakintentie en schakelt een medewerker in wanneer nodig.</p><a class="textlink" href="?view=receptionist">Open Receptionist →</a></article><article class="card agent live"><span class="agentstatus">ACTIEF</span><h2>🎯 Lead Agent</h2><p class="muted">Registreert prospects, kent scores toe, adviseert de volgende actie en kan met één klik een geprioriteerde opvolgtaak aanmaken.</p><a class="textlink" href="?view=leads">Open Leads →</a></article><article class="card agent"><span class="agentstatus">ACTIEF</span><h2>💼 Sales Agent</h2><p class="muted">Voor gestructureerde verkoopopvolging vanuit dezelfde lead- en taakdata.</p></article><article class="card agent"><span class="agentstatus">ACTIEF</span><h2>📣 Marketing Agent</h2><p class="muted">Maakt een campagnevoorstel op basis van uw bedrijfsprofiel en echte CRM-signalen.</p>${can("business")?`<button class="marketingbtn" type="button">Maak campagne</button>`:lock("business")}<div id="marketingResult" class="marketingresult"></div></article><article class="card agent"><span class="agentstatus">ACTIEF</span><h2>⭐ Review Agent</h2><p class="muted">Maakt voor gewonnen klanten een neutraal nazorg- en reviewverzoek klaar, zonder reviewmanipulatie of automatische verzending.</p></article><article class="card agent"><span class="agentstatus">ACTIEF</span><h2>🧠 JARVIS</h2><p class="muted">Analyseert CRM, taken en handoffs en routeert prioriteiten naar de juiste AI-agent.</p><a class="textlink" href="?view=jarvis">Open JARVIS →</a></article></section>`;
if(view==="settings")body=`<section class="pagehead"><span class="eyebrow">ONBOARDING & CONFIGURATIE</span><h1>Bedrijfsinstellingen</h1><p class="muted">Hoe vollediger deze informatie, hoe beter de receptionist antwoordt.</p></section><div class="card formcard"><form id="profile"><label>Bedrijfsnaam</label><input id="pname" maxlength="120" value="${esc(profile.business_name||"")}"><label>Receptionistnaam</label><input id="rname" maxlength="50" value="${esc(profile.receptionist_name||"Ava")}"><label>Beschrijving</label><textarea id="desc">${esc(profile.description||"")}</textarea><label>Diensten — één per regel</label><textarea id="services">${esc(arr(profile.services).join("\n"))}</textarea><label>Openingsuren</label><textarea id="hours">${esc(Object.entries(profile.opening_hours||{}).map(([k,v])=>k+": "+v).join("\n"))}</textarea><label>Kwalificatievragen — één per regel</label><textarea id="questions">${esc(arr(profile.qualification_questions).join("\n"))}</textarea><label>Doorgeven aan medewerker wanneer…</label><textarea id="escalations">${esc(arr(profile.escalation_rules).join("\n"))}</textarea><label>Welkomstbericht widget</label><input id="greeting" maxlength="180" value="${esc(profile.widget_greeting||"Hallo! Waarmee kan ik helpen?")}"><label>Notificatie e-mail</label><input id="notify" type="email" value="${esc(profile.notification_email||"")}"><label>Voorkeurskanaal opvolging</label><select id="followchannel"><option value="auto" ${profile.preferred_followup_channel==="auto"?"selected":""}>Automatisch</option><option value="email" ${profile.preferred_followup_channel==="email"?"selected":""}>E-mail</option><option value="whatsapp" ${profile.preferred_followup_channel==="whatsapp"?"selected":""}>WhatsApp</option></select><label class="check"><input id="autoenabled" type="checkbox" ${profile.automation_enabled?"checked":""}> Automatische workflow actief</label><div class="privacytools"><button id="exportData" type="button" class="ghostbtn">Exporteer mijn gegevens</button><div id="exportMsg" class="muted"></div></div><label class="check"><input id="wenabled" type="checkbox" ${profile.widget_enabled!==false?"checked":""}> Publieke receptionist actief</label><button>Instellingen opslaan</button></form><div id="pmsg" class="result muted"></div></div>`;
if(view==="integrations"){const emailInt=byChannel("email"),waInt=byChannel("whatsapp"),calInt=byChannel("calendar"),payInt=byChannel("payment");body=`<section class="pagehead"><span class="eyebrow">PROVIDER ROUTER</span><h1>Integraties</h1><p class="muted">Credentials worden versleuteld server-side opgeslagen en nooit teruggestuurd naar de browser. Alleen actieve tenant-integraties mogen workflowacties uitvoeren.</p></section>${readinessHtml}<section class="twocol"><div class="card formcard"><h2>E-mail · Resend</h2><p class="muted">Status: <b>${esc(emailInt?.status||"needs_setup")}</b></p><form id="emailIntegration"><label>Afzendernaam</label><input id="resendName" value="${esc(emailInt?.config?.sender_name||profile.business_name||"")}"><label>Afzender e-mail</label><input id="resendEmail" type="email" value="${esc(emailInt?.config?.sender_email||"")}"><label>Reply-to</label><input id="resendReply" type="email" value="${esc(emailInt?.config?.reply_to||"")}"><label>Reviewlink</label><input id="resendReview" type="url" value="${esc(emailInt?.config?.review_url||"")}"><label>Resend API-key</label><input id="resendSecret" type="password" autocomplete="new-password" placeholder="${emailInt?.status==="active"?"Leeg laten om bestaande key te behouden":"re_…"}"><p class="muted">Bij activatie sturen we één technische testmail naar het notificatieadres. Alleen bij API-acceptatie wordt deze koppeling actief.</p><label class="check"><input id="resendActive" type="checkbox" ${emailInt?.status==="active"?"checked":""}> Verifiëren en activeren</label><button>Veilig opslaan</button><button id="disconnectEmail" type="button" class="ghostbtn">Verbinding uitschakelen</button></form><div id="emailIntegrationMsg" class="result muted"></div></div><div class="card formcard"><h2>WhatsApp · Meta Cloud API</h2><p class="muted">Status: <b>${esc(waInt?.status||"needs_setup")}</b></p><form id="waIntegration"><label>Phone Number ID</label><input id="waPhoneId" value="${esc(waInt?.config?.phone_number_id||"")}"><label>Graph API-versie</label><input id="waApiVersion" placeholder="v23.0" value="${esc(waInt?.config?.api_version||"")}"><label>Access token</label><input id="waSecret" type="password" autocomplete="new-password" placeholder="${waInt?.status==="active"?"Leeg laten om bestaande token te behouden":"Permanent access token"}"><label>Template mapping (JSON)</label><textarea id="waTemplates" spellcheck="false">${esc(JSON.stringify(waInt?.config?.templates||{},null,2))}</textarea><label>Reviewlink</label><input id="waReview" type="url" value="${esc(waInt?.config?.review_url||"")}"><label class="check"><input id="waActive" type="checkbox" ${waInt?.status==="active"?"checked":""}> Verbinding verifiëren en activeren</label><button>Veilig opslaan</button><button id="disconnectWa" type="button" class="ghostbtn">Verbinding uitschakelen</button></form><div id="waIntegrationMsg" class="result muted"></div></div></section><section class="twocol"><div class="card formcard"><h2>Agenda · Google Calendar</h2><p class="muted">Status: <b>${esc(calInt?.status||"needs_setup")}</b></p>${qs.get("calendar")==="connected"?'<div class="successbanner"><b>Google Calendar verbonden.</b> Geblokkeerde kalenderjobs worden automatisch hervat.</div>':""}${qs.get("calendar")==="error"?`<div class="notice"><b>Google Calendar kon niet worden gekoppeld.</b> ${esc(qs.get("reason")||"Onbekende fout")}</div>`:""}<p class="muted">Elke organisatie koppelt haar eigen Google-account via OAuth. Refresh tokens worden versleuteld in Vault bewaard.</p><label>OAuth redirect URI</label><div class="result copyrow"><code id="calendarRedirectUri">https://ndecxbsrxspkuxjsbndq.supabase.co/functions/v1/google-calendar-oauth-callback</code><button class="copybtn" data-copy="calendarRedirectUri" type="button">Kopieer</button></div><p class="muted">Scope: Google Calendar events. De runner maakt, wijzigt en verwijdert alleen afspraak-events voor deze tenant.</p><button id="connectCalendar" type="button">${calInt?.status==="active"?"Opnieuw autoriseren":"Google Agenda koppelen"}</button><button id="disconnectCalendar" type="button" class="ghostbtn">Verbinding uitschakelen</button><div id="calendarIntegrationMsg" class="result muted"></div></div><div class="card formcard"><h2>Betaling · Stripe Checkout</h2><p class="muted">Status: <b>${esc(payInt?.status||"needs_setup")}</b>${payInt?.config?.stripe_mode?` · modus: <b>${esc(payInt.config.stripe_mode)}</b>`:""}</p><form id="stripeIntegration"><label>Succes-URL</label><input id="stripeSuccess" type="url" placeholder="https://uwsite.be/betaling-gelukt" value="${esc(payInt?.config?.success_url||"")}"><label>Annuleer-URL</label><input id="stripeCancel" type="url" placeholder="https://uwsite.be/betaling-geannuleerd" value="${esc(payInt?.config?.cancel_url||"")}"><label>Omschrijving betaalitem</label><input id="stripeProduct" value="${esc(payInt?.config?.product_name||("Betaling "+(profile.business_name||"")))}"><label>Stripe secret/restricted key</label><input id="stripeSecret" type="password" autocomplete="new-password" placeholder="${payInt?.status==="active"?"Leeg laten om bestaande key te behouden":"sk_… of rk_…"}"><label>Webhook signing secret <span class="muted">(optioneel)</span></label><input id="stripeWebhookSecret" type="password" autocomplete="new-password" placeholder="${payInt?.status==="active"?"Leeg laten om bestaande secret te behouden":"Leeg = automatisch webhook aanmaken"}"><label>Webhook endpoint</label><div class="result copyrow"><code id="paymentWebhookUrl">https://ndecxbsrxspkuxjsbndq.supabase.co/functions/v1/customer-payment-webhook?integration_id=${encodeURIComponent(payInt?.id||"")}</code><button class="copybtn" data-copy="paymentWebhookUrl" type="button">Kopieer</button></div><p class="muted">Met voldoende Stripe-rechten maakt mijn.ai deze webhook automatisch aan en bewaart het signing secret versleuteld. Bij een beperkte key kunt u hem handmatig aanmaken en het whsec_-secret invullen.</p><label class="check"><input id="stripeActive" type="checkbox" ${payInt?.status==="active"?"checked":""}> Stripe-account verifiëren en activeren</label><button>Veilig opslaan</button><button id="disconnectStripe" type="button" class="ghostbtn">Verbinding uitschakelen</button></form><div id="stripeIntegrationMsg" class="result muted"></div></div></section>`;}
if(view==="receptionist")body=`<section class="pagehead"><span class="eyebrow">AI-RECEPTIONIST</span><h1>Testen & publiceren</h1><p class="muted">Test Ava zoals een klant haar ervaart en plaats daarna de widget op uw website.</p></section><section class="twocol"><div class="card"><h2>Live widget</h2><p class="muted">Deelbare URL</p><div class="result copyrow"><b id="widgetUrl">${esc(location.origin+"/?widget="+profile.widget_token)}</b><button class="copybtn" data-copy="widgetUrl">Kopieer</button></div><p class="muted">Embedcode</p><div class="result copyrow"><code id="embedCode">&lt;iframe src="${esc(location.origin+"/?widget="+profile.widget_token)}" width="100%" height="650" style="border:0;border-radius:16px"&gt;&lt;/iframe&gt;</code><button class="copybtn" data-copy="embedCode">Kopieer</button></div></div><div class="card chatcard"><h2>${esc(profile.receptionist_name||"Ava")} testen</h2><form id="chat"><div class="chatmeta"><input id="cname" placeholder="Naam prospect"><input id="cemail" placeholder="E-mail (optioneel)" type="email"><input id="cphone" placeholder="Telefoon (optioneel)" type="tel"></div><label class="check consentline"><input id="cconsent" type="checkbox"> Contacttoestemming voor deze testlead.</label><label class="check consentline"><input id="cmarketing" type="checkbox"> Retentietoestemming voor deze testlead.</label><div id="chatlog" class="chatlog"><div class="bubble ai">Hallo, ik ben ${esc(profile.receptionist_name||"Ava")}. Waarmee kan ik helpen?</div></div><div class="chatrow"><input id="cmsg" placeholder="Typ een klantvraag…" required><button class="send">Verstuur</button></div></form><div id="cstatus" class="muted"></div></div></section>`;
if(view==="billing")body=`<section class="pagehead"><span class="eyebrow">ABONNEMENT</span><h1>Facturatie</h1><p class="muted">Huidig plan: <b>${esc(orgrow?.plan||"trial")}</b> · status ${esc(orgrow?.subscription_status||"trialing")}.</p></section>${trialActive?`<div class="notice"><b>Gratis proefperiode tot ${esc(trialEndLabel)}.</b> Geen kredietkaart nodig. Als u nu een betaald plan kiest, start de betaling via Stripe meteen.</div>`:""}<div class="plans appplans"><article class="card plan"><h3>Starter</h3><div class="bigprice">€99<span>/mnd</span></div><button class="pricebtn billingplan" data-plan="starter">Kies Starter</button></article><article class="card plan featured"><h3>Pro</h3><div class="bigprice">€199<span>/mnd</span></div><button class="pricebtn billingplan" data-plan="pro">Kies Pro</button></article><article class="card plan"><h3>Business</h3><div class="bigprice">€349<span>/mnd</span></div><button class="pricebtn billingplan" data-plan="business">Kies Business</button></article></div><div id="billingMsg" class="result muted"></div><a class="ghostbtn portal" href="https://billing.stripe.com/p/login/aFaaEY1wRgg765U4Iu6EU01">Facturen, betaalmethode of abonnement beheren</a>`;
if(qs.get("billing")==="success")body=(paidActive&&orgrow?.plan!=="trial"?'<div class="successbanner"><b>Abonnement actief.</b> Stripe heeft uw betaalde plan bevestigd.</div>':'<div class="successbanner"><b>Checkout afgerond.</b> Uw abonnement wordt actief zodra Stripe de betaling heeft bevestigd. Vernieuw deze pagina over enkele seconden als de status nog niet is bijgewerkt.</div>')+body;app.innerHTML=shell(body);document.querySelectorAll(".billingplan").forEach(b=>b.onclick=async()=>{const m=document.querySelector("#billingMsg");b.disabled=true;if(m)m.textContent="Veilige Stripe-checkout wordt voorbereid…";const {data,error}=await supabase.functions.invoke("billing-link",{body:{plan:b.dataset.plan}});if(error||data?.error){b.disabled=false;if(m)m.textContent="Checkout kon niet starten: "+(data?.detail||data?.error||error?.message||"onbekende fout");return}location.assign(data.checkout_url)});
const hc=document.querySelector("#healthCheck");if(hc)hc.onclick=async()=>{const m=document.querySelector("#healthResult");hc.disabled=true;m.textContent="Backend wordt gecontroleerd…";const {data,error}=await supabase.functions.invoke("tenant-health",{body:{}});hc.disabled=false;if(error||data?.error){m.textContent="Backendcontrole mislukt: "+(data?.error||error?.message||"onbekende fout");return}const r=data.readiness||{},w=data.workflow||{};m.innerHTML=`<b>${esc(String(r.status||"onbekend").toUpperCase())}</b><br>Profiel: ${r.profile?"✓":"○"} · Owner-notificatie: ${r.owner_notification?"✓":"○"} · Leadopvolging: ${r.outbound?"✓":"○"} · Lifecycle: ${r.lifecycle_ready?"✓":"○"} · Agenda: ${r.calendar?"✓":"○"} · Betaling: ${r.payment?"✓":"○"}${r.payment_connected&&!r.payment?" (testmodus)":""} · SaaS billing: ${r.saas_billing?"✓":"○"}<br><span class="muted">Queue: ${esc(w.pending||0)} pending · ${esc(w.blocked||0)} blocked · ${esc(w.failed||0)} failed · ${esc(w.open_handoffs||0)} handoffs</span>`};
const runOperation=async(body,msg)=>{if(msg)msg.textContent="Verwerkt…";const {data,error}=await supabase.functions.invoke("operations-admin",{body});if(error||data?.error){if(msg)msg.textContent="Mislukt: "+(data?.detail||data?.error||error?.message||"onbekende fout");return false}if(msg)msg.textContent="✓ Verwerkt";setTimeout(()=>dashboard(),400);return true};
document.querySelectorAll(".apptform").forEach(form=>form.onsubmit=async e=>{e.preventDefault();const m=document.querySelector("#op-"+form.dataset.id),fd=new FormData(form),start=String(fd.get("start")||""),end=String(fd.get("end")||"");await runOperation({action:"schedule_appointment",appointment_id:form.dataset.id,start_at:start?new Date(start).toISOString():"",end_at:end?new Date(end).toISOString():"",timezone:"Europe/Brussels",location:String(fd.get("location")||""),status:String(fd.get("status")||"proposed")},m)});
document.querySelectorAll(".confirmappt").forEach(b=>b.onclick=()=>runOperation({action:"confirm_appointment",appointment_id:b.dataset.id},document.querySelector("#op-"+b.dataset.id)));
document.querySelectorAll(".completeappt").forEach(b=>b.onclick=()=>runOperation({action:"complete_appointment",appointment_id:b.dataset.id},document.querySelector("#op-"+b.dataset.id)));
document.querySelectorAll(".cancelappt").forEach(b=>b.onclick=()=>runOperation({action:"cancel_appointment",appointment_id:b.dataset.id},document.querySelector("#op-"+b.dataset.id)));
document.querySelectorAll(".paymentform").forEach(form=>form.onsubmit=async e=>{e.preventDefault();const amount=Number(new FormData(form).get("amount")),m=document.querySelector("#op-"+form.dataset.appt);if(!Number.isFinite(amount)||amount<=0){m.textContent="Vul een geldig bedrag in.";return}await runOperation({action:"create_payment",appointment_id:form.dataset.appt,lead_id:form.dataset.lead,amount_cents:Math.round(amount*100),currency:"EUR"},m)});
document.querySelectorAll(".retryworkflow").forEach(b=>b.onclick=async()=>{const m=document.querySelector("#wf-"+b.dataset.id),unknown=b.dataset.unknown==="1";if(unknown&&!confirm("De vorige WhatsApp-poging heeft een onbekende leveringsstatus. Opnieuw proberen kan een dubbel klantbericht veroorzaken. Toch opnieuw sturen?"))return;await runOperation({action:"retry_workflow_action",workflow_action_id:b.dataset.id,confirm_delivery_unknown:unknown},m)});
const saveIntegration=async(id,body,msgEl)=>{msgEl.textContent="Veilig opslaan…";const {data,error}=await supabase.functions.invoke("integration-admin",{body:{integration_id:id,...body}});if(error||data?.error){msgEl.textContent="Niet opgeslagen: "+(data?.detail||data?.error||error?.message||"onbekende fout");return false}msgEl.textContent="✓ Integratie opgeslagen";return true};
const emailForm=document.querySelector("#emailIntegration");if(emailForm)emailForm.onsubmit=async e=>{e.preventDefault();const i=byChannel("email"),m=document.querySelector("#emailIntegrationMsg");if(!i){m.textContent="E-mailintegratie ontbreekt.";return}const ok=await saveIntegration(i.id,{action:"configure",secret:document.querySelector("#resendSecret").value.trim(),activate:document.querySelector("#resendActive").checked,config:{sender_name:document.querySelector("#resendName").value.trim(),sender_email:document.querySelector("#resendEmail").value.trim(),reply_to:document.querySelector("#resendReply").value.trim(),review_url:document.querySelector("#resendReview").value.trim()}},m);if(ok)setTimeout(()=>dashboard(),500)};
const waForm=document.querySelector("#waIntegration");if(waForm)waForm.onsubmit=async e=>{e.preventDefault();const i=byChannel("whatsapp"),m=document.querySelector("#waIntegrationMsg");if(!i){m.textContent="WhatsApp-integratie ontbreekt.";return}let templates={};try{templates=JSON.parse(document.querySelector("#waTemplates").value||"{}")}catch{m.textContent="Template mapping bevat ongeldige JSON.";return}const ok=await saveIntegration(i.id,{action:"configure",secret:document.querySelector("#waSecret").value.trim(),activate:document.querySelector("#waActive").checked,config:{phone_number_id:document.querySelector("#waPhoneId").value.trim(),api_version:document.querySelector("#waApiVersion").value.trim(),templates,review_url:document.querySelector("#waReview").value.trim()}},m);if(ok)setTimeout(()=>dashboard(),500)};
const calendarConnect=document.querySelector("#connectCalendar");if(calendarConnect)calendarConnect.onclick=async()=>{const m=document.querySelector("#calendarIntegrationMsg");calendarConnect.disabled=true;m.textContent="Veilige Google-koppeling voorbereiden…";const {data,error}=await supabase.functions.invoke("google-calendar-oauth-start",{body:{}});if(error||data?.error){calendarConnect.disabled=false;m.textContent=(data?.code==="google_oauth_platform_setup_required"?"Google OAuth-platformconfiguratie ontbreekt. Voeg in Google Cloud exact deze redirect URI toe: "+(data?.redirect_uri||""):"Koppeling kon niet starten: "+(data?.detail||data?.error||error?.message||"onbekende fout"));return}location.assign(data.authorization_url)};
const stripeForm=document.querySelector("#stripeIntegration");if(stripeForm)stripeForm.onsubmit=async e=>{e.preventDefault();const i=byChannel("payment"),m=document.querySelector("#stripeIntegrationMsg");if(!i){m.textContent="Stripe-integratie ontbreekt.";return}const ok=await saveIntegration(i.id,{action:"configure",secret:document.querySelector("#stripeSecret").value.trim(),webhook_secret:document.querySelector("#stripeWebhookSecret").value.trim(),activate:document.querySelector("#stripeActive").checked,config:{success_url:document.querySelector("#stripeSuccess").value.trim(),cancel_url:document.querySelector("#stripeCancel").value.trim(),product_name:document.querySelector("#stripeProduct").value.trim()}},m);if(ok)setTimeout(()=>dashboard(),500)};
const disconnectIntegration=async(ch,msgSelector)=>{const i=byChannel(ch),m=document.querySelector(msgSelector);if(!i||!m)return;m.textContent="Verbinding uitschakelen…";const {data,error}=await supabase.functions.invoke("integration-admin",{body:{integration_id:i.id,action:"disconnect"}});if(error||data?.error){m.textContent="Uitschakelen mislukt: "+(data?.detail||data?.error||error?.message);return}m.textContent="✓ Verbinding uitgeschakeld";setTimeout(()=>dashboard(),500)};
const de=document.querySelector("#disconnectEmail");if(de)de.onclick=()=>disconnectIntegration("email","#emailIntegrationMsg");
const dw=document.querySelector("#disconnectWa");if(dw)dw.onclick=()=>disconnectIntegration("whatsapp","#waIntegrationMsg");const dc=document.querySelector("#disconnectCalendar");if(dc)dc.onclick=()=>disconnectIntegration("calendar","#calendarIntegrationMsg");const ds=document.querySelector("#disconnectStripe");if(ds)ds.onclick=()=>disconnectIntegration("payment","#stripeIntegrationMsg");
const mb=document.querySelector(".marketingbtn");if(mb)mb.onclick=async()=>{const out=document.querySelector("#marketingResult");mb.disabled=true;mb.textContent="Analyseert CRM…";const {data,error}=await supabase.functions.invoke("marketing-agent-action",{body:{}});mb.disabled=false;mb.textContent="Maak campagne";if(error||data?.error){out.textContent="Campagnevoorstel mislukt";return}out.innerHTML=`<b>${esc(data.objective)}</b><p>${esc(data.hook)}</p><p>${esc(data.content)}</p><p><b>CTA:</b> ${esc(data.cta)}</p>`};document.querySelector("#logout").onclick=async()=>{await supabase.auth.signOut();location.href="./"};const mn=document.querySelector("#mobileNav");if(mn)mn.onchange=()=>location.href="?view="+mn.value;document.querySelectorAll(".donebtn").forEach(b=>b.onclick=async()=>{const {error}=await supabase.from("tasks").update({status:"done",completed_at:new Date().toISOString()}).eq("id",b.dataset.id).eq("organization_id",org);if(error)alert(error.message);else dashboard()});document.querySelectorAll(".copybtn").forEach(b=>b.onclick=async()=>{const el=document.getElementById(b.dataset.copy);await navigator.clipboard.writeText(el.innerText);const old=b.textContent;b.textContent="Gekopieerd ✓";setTimeout(()=>b.textContent=old,1200)});document.querySelectorAll(".reviewbtn").forEach(b=>b.onclick=async()=>{const out=document.getElementById("review-"+b.dataset.id);b.disabled=true;b.textContent="Maakt nazorg…";const {data,error}=await supabase.functions.invoke("review-agent-action",{body:{lead_id:b.dataset.id}});b.disabled=false;b.textContent="Review Agent";if(error||data?.error){out.textContent="Nazorgvoorstel mislukt";return}out.textContent="Kanaal: "+data.channel+" | Bericht: "+data.message});document.querySelectorAll(".salesbtn").forEach(b=>b.onclick=async()=>{const out=document.getElementById("sales-"+b.dataset.id);b.disabled=true;b.textContent="Analyseert…";const {data,error}=await supabase.functions.invoke("sales-agent-action",{body:{lead_id:b.dataset.id}});b.disabled=false;b.textContent="Sales Agent";if(error||data?.error){out.textContent="Analyse mislukt";return}out.textContent="Actie: "+data.action+" | Kanaal: "+data.channel+" | Bericht: "+data.message});document.querySelectorAll(".followbtn").forEach(b=>b.onclick=async()=>{b.disabled=true;b.textContent="Wordt ingepland…";const {data,error}=await supabase.functions.invoke("lead-agent-action",{body:{lead_id:b.dataset.id,action:"follow_up"}});if(error||data?.error){b.disabled=false;b.textContent="Opnieuw proberen";alert(data?.error||error.message);return}await dashboard()});document.querySelectorAll(".leadstatus").forEach(el=>el.onchange=async()=>{const {error}=await supabase.from("leads").update({status:el.value,updated_at:new Date().toISOString()}).eq("id",el.dataset.id).eq("organization_id",org);if(error)alert(error.message)});
const ex=document.querySelector("#exportData");if(ex)ex.onclick=async()=>{ex.disabled=true;const m=document.querySelector("#exportMsg");m.textContent="Export wordt gemaakt…";const {data,error}=await supabase.rpc("export_my_account");ex.disabled=false;if(error){m.textContent="Export mislukt: "+error.message;return}const blob=new Blob([JSON.stringify(data,null,2)],{type:"application/json"}),u=URL.createObjectURL(blob),a=document.createElement("a");a.href=u;a.download="mijn-ai-export.json";a.click();URL.revokeObjectURL(u);m.textContent="✓ Export aangemaakt"};
const pf=document.querySelector("#profile");if(pf)pf.onsubmit=async e=>{e.preventDefault();const lines=id=>document.querySelector(id).value.split("\n").map(x=>x.trim()).filter(Boolean).slice(0,20),hours=Object.fromEntries(document.querySelector("#hours").value.split("\n").map(x=>x.split(":")).filter(x=>x.length>1).map(([k,...v])=>[k.trim(),v.join(":").trim()]));const {error}=await supabase.from("business_profiles").update({business_name:document.querySelector("#pname").value.trim(),receptionist_name:document.querySelector("#rname").value.trim()||"Ava",description:document.querySelector("#desc").value.trim(),services:lines("#services"),opening_hours:hours,qualification_questions:lines("#questions"),escalation_rules:lines("#escalations"),widget_greeting:document.querySelector("#greeting").value.trim()||"Hallo! Waarmee kan ik helpen?",notification_email:document.querySelector("#notify").value.trim()||null,preferred_followup_channel:document.querySelector("#followchannel").value,automation_enabled:document.querySelector("#autoenabled").checked,widget_enabled:document.querySelector("#wenabled").checked,updated_at:new Date().toISOString()}).eq("organization_id",org);document.querySelector("#pmsg").textContent=error?error.message:"✓ Instellingen opgeslagen"};
let chatLead=null,chatConv=null;const cf=document.querySelector("#chat");if(cf)cf.onsubmit=async e=>{e.preventDefault();const input=document.querySelector("#cmsg"),status=document.querySelector("#cstatus"),log=document.querySelector("#chatlog"),message=input.value.trim();if(!message)return;log.insertAdjacentHTML("beforeend",`<div class="bubble customer">${esc(message)}</div>`);input.value="";status.textContent="AI verwerkt…";const {data,error}=await supabase.functions.invoke("reception-chat",{body:{message,name:document.querySelector("#cname").value.trim(),email:document.querySelector("#cemail").value.trim(),phone:document.querySelector("#cphone").value.trim(),contact_consent:document.querySelector("#cconsent").checked,marketing_consent:document.querySelector("#cmarketing").checked,lead_id:chatLead,conversation_id:chatConv}});if(error){status.textContent="Fout: "+error.message;return}chatLead=data.lead_id;chatConv=data.conversation_id;log.insertAdjacentHTML("beforeend",`<div class="bubble ai">${esc(data.reply)}</div>`);status.textContent="✓ Opgeslagen in CRM";log.scrollTop=log.scrollHeight}}

supabase.auth.onAuthStateChange((event,session)=>{if(event==="SIGNED_OUT")authView();if(event==="PASSWORD_RECOVERY"&&!location.search.includes("recovery=1"))location.href="./?recovery=1"});
const qs=new URLSearchParams(location.search);const recovery=qs.get("recovery")==="1";if(recovery){app.innerHTML='<main class="shell"><section class="card formcard"><div class="brand">Reception AI</div><h1>Nieuw wachtwoord</h1><p class="muted">Kies een nieuw wachtwoord van minstens 8 tekens.</p><form id="recoveryForm"><input id="newpass" type="password" minlength="8" required placeholder="Nieuw wachtwoord"><button>Wachtwoord opslaan</button></form><div id="recoveryMsg" class="result muted"></div></section></main>';document.querySelector("#recoveryForm").onsubmit=async e=>{e.preventDefault();const m=document.querySelector("#recoveryMsg");const {error}=await supabase.auth.updateUser({password:document.querySelector("#newpass").value});if(error)m.textContent=error.message;else{m.textContent="✓ Wachtwoord gewijzigd. U wordt doorgestuurd…";setTimeout(()=>location.href="./",900)}}}const widget=qs.get("widget");if(!recovery&&widget)publicWidgetView(widget);else if(!recovery){const page=qs.get("page");if(page==="privacy"||page==="terms")legalView(page);else{const {data:{session}}=await supabase.auth.getSession();session?dashboard():authView();}}